contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public payable {
        require(loanToCollateral > 0, "loanToCollateral must be > 0");
        require(duration > 0, "duration must be > 0");

        uint256 reqID = c.requestLoan(amount, interest, loanToCollateral, duration); if (__ESBMC_reverted()) return;

        uint256 loanID = c.clearRequest(reqID, false, false); if (__ESBMC_reverted()) return;

        c.approveTransfer(msg.sender, loanID); if (__ESBMC_reverted()) return;

        c.transferOwnership(loanID); if (__ESBMC_reverted()) return;

        address afterApproval = c.approvals(loanID); if (__ESBMC_reverted()) return;

        bool secondReverted;
        c.transferOwnership(loanID); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        assert(afterApproval == address(0) && secondReverted);
    }
}

