pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) internal {
        vm.assume(loanToCollateral > 0);
        vm.assume(duration > 0);
        uint256 reqID;
        try c.requestLoan(amount, interest, loanToCollateral, duration) returns (uint256 __r) { reqID = __r; } catch { return; }
        uint256 loanID;
        try c.clearRequest(reqID, false, false) returns (uint256 __r) { loanID = __r; } catch { return; }
        try c.approveTransfer(msg.sender, loanID) {} catch { return; }
        try c.transferOwnership(loanID) {} catch { return; }
        address afterApproval;
        try c.approvals(loanID) returns (address __r) { afterApproval = __r; } catch { return; }
        bool secondReverted;
        try c.transferOwnership(loanID) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        assertTrue(afterApproval == address(0) && secondReverted);
    }

    function testFuzz_run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public {
        _run(amount, interest, loanToCollateral, duration);
    }

    receive() external payable {}
}
